from collections import defaultdict, deque


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self.customers: dict[str, bool] = {}
        self.tickets: dict[int, dict] = {}
        self._next_id = 1
        # Queues keyed by (vip, priority) so VIP always beats non-VIP.
        self._queues: dict[tuple[bool, str], deque[int]] = {
            (vip, prio): deque()
            for vip in (True, False)
            for prio in self.PRIORITIES
        }
        self._priority_rank = {"critical": 0, "high": 1, "normal": 2}

    def add_customer(self, name: str, vip: bool = False) -> None:
        self.customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title must not be empty.")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority!r}")
        vip = self.customers.get(customer, False)
        ticket_id = self._next_id
        self._next_id += 1
        self.tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "vip": vip,
            "status": "open",
        }
        self._queues[(vip, priority)].append(ticket_id)
        return ticket_id

    def next_ticket(self) -> int | None:
        for vip in (True, False):
            for prio in self.PRIORITIES:
                queue = self._queues[(vip, prio)]
                while queue:
                    ticket_id = queue.popleft()
                    ticket = self.tickets.get(ticket_id)
                    if ticket is not None and ticket["status"] == "open":
                        ticket["status"] = "in_progress"
                        return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        ticket = self.tickets.get(ticket_id)
        if ticket is None:
            raise KeyError(f"Unknown ticket id: {ticket_id}")
        ticket["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        ticket = self.tickets.get(ticket_id)
        if ticket is None:
            raise KeyError(f"Unknown ticket id: {ticket_id}")
        if ticket["status"] == "open":
            return
        ticket["status"] = "open"
        self._queues[(ticket["vip"], ticket["priority"])].append(ticket_id)
